120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        validateRequiredOwnerFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setAddress(normalizeAddress(owner.getAddress()));
125	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
126	        owner.setTelephone(normalizedTelephone);
127	        rejectDuplicateTelephone(normalizedTelephone);
128	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
129	        owner.setEmail(normalizeEmail(owner.getEmail()));
130	        if (owner.getRegistrationDate() == null) {
131	            owner.setRegistrationDate(LocalDate.now());
132	        }
133	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
134	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
135	        this.clinicService.saveOwner(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        currentOwner.setAddress(ownerFieldsDto.getAddress());
150	        currentOwner.setCity(ownerFieldsDto.getCity());
151	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
152	        currentOwner.setLastName(ownerFieldsDto.getLastName());
153	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
154	        this.clinicService.saveOwner(currentOwner);
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        this.clinicService.deleteOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
237	     * offending field is collected so the caller learns exactly which values must be supplied.
238	     *
239	     * @param ownerFieldsDto the submitted owner payload
240	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
241	     *         telephone is missing or blank
242	     */
243	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
244	        List<String> missingFields = new ArrayList<>();
245	        if (isBlank(ownerFieldsDto.getFirstName())) {
246	            missingFields.add("firstName");
247	        }
248	        if (isBlank(ownerFieldsDto.getLastName())) {
249	            missingFields.add("lastName");
250	        }
251	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
252	            missingFields.add("address");
253	        }
254	        if (isBlank(ownerFieldsDto.getCity())) {
255	            missingFields.add("city");
256	        }
257	        if (isBlank(ownerFieldsDto.getTelephone())) {
258	            missingFields.add("telephone");
259	        }
260	        if (!missingFields.isEmpty()) {
261	            throw new MissingOwnerFieldsException(missingFields);
262	        }
263	    }
264	
265	    private boolean isBlank(String value) {
266	        return value == null || value.isBlank();
267	    }
268	
269	    /**
270	     * Counts the existing owners who, before this create, already share the given first and last name.
271	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
272	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
273	     * case or spacing still count as the same name.
274	     *
275	     * @param firstName the first name of the owner being created
276	     * @param lastName the last name of the owner being created
277	     * @return the number of existing owners sharing both names (zero when none)
278	     */
279	    private int countNamesakes(String firstName, String lastName) {
280	        String first = normalizeHouseholdField(firstName);
281	        String last = normalizeHouseholdField(lastName);
282	        return (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
284	                && normalizeHouseholdField(existing.getLastName()).equals(last))
285	            .count();
286	    }
287	
288	    /**
289	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
290	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
291	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
292	     *
293	     * @param lastName the owner's last name
294	     * @return the formatted customer code
295	     */
296	    private String generateCustomerCode(String lastName) {
297	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
298	        int sequence = this.clinicService.findAllOwners().size() + 1;
299	        return String.format("%s-%04d", last3, sequence);
300	    }
301	
302	    /**
303	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
304	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
305	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
306	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
307	     * stored and returned.
308	     *
309	     * @param telephone the raw telephone value from the request
310	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
311	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
312	     */
313	    private String normalizeTelephone(String telephone) {
314	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
315	        String e164;
316	        if (cleaned.startsWith("+")) {
317	            e164 = cleaned;
318	        } else {
319	            String national = cleaned;
320	            if (national.startsWith("0")) {
321	                national = national.substring(1);
322	            }
323	            e164 = "+61" + national;
324	        }
325	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
326	            throw new InvalidOwnerFieldsException(List.of("telephone"));
327	        }
328	        return e164;
329	    }
330	
331	    /**
332	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
333	     * left unset. When a value is present it must be a syntactically valid address; the normalized
334	     * form stored and returned is the value lower-cased.
335	     *
336	     * @param email the raw email value from the request, or {@code null} when none was supplied
337	     * @return the lower-cased email, or {@code null} when no email was supplied
338	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
339	     */
340	    private String normalizeEmail(String email) {
341	        if (email == null || email.isBlank()) {
342	            return null;
343	        }
344	        if (!EMAIL_PATTERN.matcher(email).matches()) {
345	            throw new InvalidOwnerFieldsException(List.of("email"));
346	        }
347	        return email.toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
352	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
353	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
354	     * normalized form is what gets stored, returned and used for every address comparison (the
355	     * required-field check, household duplicate detection and the shared household id).
356	     *
357	     * @param address the raw address value from the request, or {@code null}
358	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
359	     */
360	    private String normalizeAddress(String address) {
361	        if (address == null) {
362	            return "";
363	        }
364	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
365	        if (collapsed.isEmpty()) {
366	            return "";
367	        }
368	        String[] tokens = collapsed.split(" ");
369	        for (int i = 0; i < tokens.length; i++) {
370	            switch (tokens[i]) {
371	                case "ST" -> tokens[i] = "STREET";
372	                case "RD" -> tokens[i] = "ROAD";
373	                case "AVE" -> tokens[i] = "AVENUE";
374	                default -> { }
375	            }
376	        }
377	        return String.join(" ", tokens);
378	    }
379	
380	    /**
381	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
382	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
383	     * directly and is therefore independent of the punctuation a caller supplied.
384	     *
385	     * @param e164Telephone the E.164 telephone of the owner being created
386	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
387	     */
388	    private void rejectDuplicateTelephone(String e164Telephone) {
389	        boolean inUse = this.clinicService.findAllOwners().stream()
390	            .map(Owner::getTelephone)
391	            .filter(existing -> existing != null)
392	            .anyMatch(e164Telephone::equals);
393	        if (inUse) {
394	            throw new DuplicateOwnerTelephoneException(e164Telephone);
395	        }
396	    }
397	
398	    /**
399	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
400	     * last name and a normalized address: last names are compared case-insensitively after whitespace
401	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
402	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
403	     * abbreviation still count as the same household.
404	     * <p>
405	     * When the owner's last name and address already belong to at least one other owner the behaviour
406	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
407	     * household. If it is true the create is allowed and every member of the household - the existing
408	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
409	     * read. When no other owner shares the last name and address no identifier is assigned.
410	     *
411	     * @param owner the owner being created
412	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
413	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
414	     *         address and {@code sharesHousehold} is not true
415	     */
416	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
417	        String lastName = normalizeHouseholdField(owner.getLastName());
418	        String address = normalizeAddress(owner.getAddress());
419	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
420	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
421	                && normalizeAddress(existing.getAddress()).equals(address))
422	            .toList();
423	        if (housemates.isEmpty()) {
424	            return;
425	        }
426	        if (!Boolean.TRUE.equals(sharesHousehold)) {
427	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
428	        }
429	        String householdId = generateHouseholdId(lastName, address);
430	        owner.setHouseholdId(householdId);
431	        for (Owner housemate : housemates) {
432	            if (!householdId.equals(housemate.getHouseholdId())) {
433	                housemate.setHouseholdId(householdId);
434	                this.clinicService.saveOwner(housemate);
435	            }
436	        }
437	    }
438	
439	    /**
440	     * Builds the stable identifier shared by the members of one household. It is derived purely from
441	     * the normalized last name and address, so every owner of a given household deterministically
442	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
443	     * two normalized fields joined by a single space.
444	     *
445	     * @param normalizedLastName the household's last name, already normalized for comparison
446	     * @param normalizedAddress the household's address, already normalized for comparison
447	     * @return the shared household identifier
448	     */
449	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
450	        String key = normalizedLastName + '�' + normalizedAddress;
451	        try {
452	            byte[] digest = MessageDigest.getInstance("SHA-256")
453	                .digest(key.getBytes(StandardCharsets.UTF_8));
454	            StringBuilder hex = new StringBuilder();
455	            for (byte b : digest) {
456	                hex.append(String.format("%02X", b));
457	                if (hex.length() >= 12) {
458	                    break;
459	                }
460	            }
461	            return hex.substring(0, 12);
462	        } catch (NoSuchAlgorithmException e) {
463	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
464	        }
465	    }
466	
467	    /**
468	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
469	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
470	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
471	     * expands common abbreviations.
472	     *
473	     * @param value the raw last name, or {@code null}
474	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
475	     */
476	    private String normalizeHouseholdField(String value) {
477	        if (value == null) {
478	            return "";
479	        }
480	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
481	    }
482	}
